// src/features/enea-shadow-crm/officialMunicipalityProvinceChanges.ts
var OFFICIAL_MUNICIPALITY_PROVINCE_CHANGE_RULE_ID = "user-2026-09-02-official-municipality-province-lineage-v1";
function normalizeExact2(value) {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().replace(/\s+/g, " ").toLocaleLowerCase("it");
}
function resolveOfficialMunicipalityProvinceChange(input) {
  const name = normalizeExact2(input.name);
  const province = normalizeExact2(input.province);
  const matches2 = OFFICIAL_MUNICIPALITY_PROVINCE_CHANGES.filter((entry) => normalizeExact2(entry.municipalityName) === name && entry.acceptedHistoricalProvinceCodes.some((code) => normalizeExact2(code) === province));
  if (matches2.length !== 1) return null;
  const [match] = matches2;
  return {
    ruleId: OFFICIAL_MUNICIPALITY_PROVINCE_CHANGE_RULE_ID,
    municipalityName: match.municipalityName,
    historicalProvinceCode: input.province.trim().toUpperCase(),
    currentProvinceCode: match.currentProvinceCode,
    currentIstatCode: match.currentIstatCode,
    previousIstatCode: match.previousIstatCode,
    effectiveDate: OFFICIAL_MUNICIPALITY_PROVINCE_CHANGES_SOURCE.effectiveDate,
    officialSourceUrl: OFFICIAL_MUNICIPALITY_PROVINCE_CHANGES_SOURCE.sourceUrl,
    officialSourceZipSha256: OFFICIAL_MUNICIPALITY_PROVINCE_CHANGES_SOURCE.sourceZipSha256,
    officialSourceCsvSha256: OFFICIAL_MUNICIPALITY_PROVINCE_CHANGES_SOURCE.sourceCsvSha256
  };
}

