function coBeneficiaryPerson(fieldsById) {
  const name = fieldsById.get("beneficiario.cointestatario_nome");
  const surname = fieldsById.get("beneficiario.cointestatario_cognome");
  const taxCode = fieldsById.get("beneficiario.cointestatario_cf");
  if (![name, surname, taxCode].every((field) => field?.status === "ready" && !field.testOnly && !isInternalPlaceholder(field.value))) return void 0;
  return {
    name: name.value,
    surname: surname.value,
    taxCode: taxCode.value.replace(/\s+/g, "").toUpperCase(),
    sourceIds: [...new Set([name.source, surname.source, taxCode.source].filter(Boolean))],
    appliedRuleIds: [.../* @__PURE__ */ new Set([...name.appliedRuleIds ?? [], ...surname.appliedRuleIds ?? [], ...taxCode.appliedRuleIds ?? []])]
  };
}
var ENEA_BENEFICIARY_PORTAL_FIELDS = [
  { fieldId: "beneficiario.nome", portalId: "id-nome", control: "input" },
  { fieldId: "beneficiario.cognome", portalId: "id-cognome", control: "input" },
  { fieldId: "beneficiario.cf", portalId: "id-codice_fiscale", control: "input" },
  { fieldId: "beneficiario.data_nascita", portalId: "id-data_nascita", control: "input" },
  { fieldId: "beneficiario.sesso", portalId: "id-sesso", control: "select" },
  { fieldId: "beneficiario.nazione_nascita", portalId: "id-nazione_nascita", control: "select" },
  { fieldId: "beneficiario.comune_nascita", portalId: "id-comune_nascita", control: "autocomplete" },
  { fieldId: "beneficiario.nazione_residenza", portalId: "id-nazione_residenza", control: "select" },
  { fieldId: "beneficiario.comune_residenza", portalId: "id-comune_residenza", control: "autocomplete" },
  { fieldId: "beneficiario.indirizzo_residenza", portalId: "id-indirizzo_residenza", control: "input" },
  { fieldId: "beneficiario.civico_residenza", portalId: "id-civico_residenza", control: "input" },
  { fieldId: "beneficiario.cap_residenza", portalId: "id-cap_residenza", control: "input" },
  { fieldId: "beneficiario.telefono", portalId: "id-telefono", control: "input" }
];
function isInternalPlaceholder(value) {
  const normalized2 = value.trim().toLocaleLowerCase("it");
  return normalized2 === "non indicato" || normalized2 === "intervento umano richiesto";
}
function buildEneaBeneficiaryPortalScript(mapped) {
  const fieldsById = new Map(
    mapped.sections.flatMap((section2) => section2.fields).map((field) => [field.id, field])
  );
  const verifiedForeignBirth = resolveForeignBirthCountryFromFiscalCode(fieldsById.get("beneficiario.cf")?.value);
  const nationIsItaly = (fieldId) => fieldsById.get(fieldId)?.value.trim().toLocaleLowerCase("it") === "italia";
  const readyFields = ENEA_BENEFICIARY_PORTAL_FIELDS.flatMap((definition) => {
    const field = fieldsById.get(definition.fieldId);
    if (!field || field.status !== "ready" || field.testOnly || isInternalPlaceholder(field.value)) return [];
    const control = definition.fieldId === "beneficiario.comune_nascita" && !nationIsItaly("beneficiario.nazione_nascita") ? "input" : definition.fieldId === "beneficiario.comune_residenza" && !nationIsItaly("beneficiario.nazione_residenza") ? "input" : definition.control;
    const selectValue = definition.fieldId === "beneficiario.nazione_nascita" ? nationIsItaly("beneficiario.nazione_nascita") ? "ita" : verifiedForeignBirth?.selectValue : definition.fieldId === "beneficiario.nazione_residenza" && nationIsItaly("beneficiario.nazione_residenza") ? "ita" : void 0;
    const isBirthMunicipality = definition.fieldId === "beneficiario.comune_nascita";
    const isResidenceMunicipality = definition.fieldId === "beneficiario.comune_residenza";
    const officialMunicipality = isBirthMunicipality ? resolveOfficialMunicipalityIdentity({
      name: field.value,
      province: fieldsById.get("beneficiario.provincia_nascita")?.value ?? ""
    }) : null;
    const officialProvinceChange = isBirthMunicipality ? resolveOfficialMunicipalityProvinceChange({
      name: field.value,
      province: fieldsById.get("beneficiario.provincia_nascita")?.value ?? ""
    }) : null;
    const supportingProvince = isBirthMunicipality ? fieldsById.get("beneficiario.provincia_nascita")?.value ?? "" : isResidenceMunicipality ? mapped.source.form.residenza.provincia : "";
    const officialCanonical = isBirthMunicipality || isResidenceMunicipality ? resolveOfficialMunicipalityCanonicalIdentity({
      name: field.value,
      province: officialProvinceChange?.currentProvinceCode ?? officialMunicipality?.provinceCode ?? supportingProvince
    }) : null;
    const autocompleteQualifier = officialCanonical?.provinceCode ?? officialProvinceChange?.currentProvinceCode ?? officialMunicipality?.provinceCode ?? (isBirthMunicipality && nationIsItaly("beneficiario.nazione_nascita") && fieldsById.get("beneficiario.provincia_nascita")?.status === "ready" ? fieldsById.get("beneficiario.provincia_nascita").value.trim().toUpperCase() : void 0);
    return [{
      ...definition,
      control,
      value: officialCanonical?.canonicalName ?? field.value,
      ...selectValue ? { selectValue } : {},
      ...autocompleteQualifier ? { autocompleteQualifier } : {},
      ...officialCanonical ? { autocompleteAuthoritativeIstatCode: officialCanonical.istatCode } : officialProvinceChange ? { autocompleteAuthoritativeIstatCode: officialProvinceChange.currentIstatCode } : {}
    }];
  });
  const readyFieldIds = readyFields.map(({ fieldId }) => fieldId);
  const readySet = new Set(readyFieldIds);
  const skippedFieldIds = ENEA_BENEFICIARY_PORTAL_FIELDS.map(({ fieldId }) => fieldId).filter((fieldId) => !readySet.has(fieldId));
  const data = JSON.stringify(readyFields.map(({ portalId, control, value, selectValue, autocompleteQualifier, autocompleteAuthoritativeIstatCode }) => ({
    portalId,
    control,
    value,
    ...selectValue ? { selectValue } : {},
    ...autocompleteQualifier ? { autocompleteQualifier } : {},
    ...autocompleteAuthoritativeIstatCode ? { autocompleteAuthoritativeIstatCode } : {}
  })));
  const coBeneficiary = coBeneficiaryPerson(fieldsById);
  const runtime = {
    fields: JSON.parse(data),
    pageName: "Anagrafica Beneficiario",
    markerIds: ["id-nome", "id-codice_fiscale"],
    successMessage: "ENEA Lab: compilazione anagrafica conclusa. Nessun salvataggio o invio eseguito.",
    ...coBeneficiary ? { coBeneficiary } : {}
  };
  const script = buildEneaPortalRuntimeScript(runtime);
  return {
    script,
    readyFieldIds: coBeneficiary ? [...readyFieldIds, "beneficiario.cointestatario_nome", "beneficiario.cointestatario_cognome", "beneficiario.cointestatario_cf"] : readyFieldIds,
    skippedFieldIds,
    runtime
  };
}

